GUARDS = """
CREATE FUNCTION guard_scan_file() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE n integer;
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'scan_source_immutable' USING ERRCODE='23514'; END IF;
 IF TG_OP='INSERT' THEN
  PERFORM 1 FROM scan_batches WHERE id=NEW.batch_id FOR UPDATE;
  SELECT count(*) INTO n FROM scan_files WHERE batch_id=NEW.batch_id;
  IF n>=20 OR NEW.status<>'receiving' OR NEW.attempt_number<>1 OR NEW.page_count IS NOT NULL THEN
   RAISE EXCEPTION 'scan_initial_state' USING ERRCODE='23514'; END IF;
 ELSE
  IF OLD.status='stored' OR to_jsonb(NEW)-ARRAY['status','attempt_token','attempt_number',
   'lease_expires_at','object_key','bucket','failure_code','page_count','updated_at'] <>
   to_jsonb(OLD)-ARRAY['status','attempt_token','attempt_number','lease_expires_at','object_key',
   'bucket','failure_code','page_count','updated_at'] THEN
   RAISE EXCEPTION 'scan_source_immutable' USING ERRCODE='23514'; END IF;
  IF NEW.attempt_token<>OLD.attempt_token THEN
   IF NEW.attempt_number<>OLD.attempt_number+1 OR NEW.status<>'receiving' OR
     (OLD.status='receiving' AND OLD.lease_expires_at>clock_timestamp()) OR
     EXISTS(SELECT 1 FROM scan_pages WHERE file_id=OLD.id) THEN
    RAISE EXCEPTION 'scan_attempt_conflict' USING ERRCODE='23514'; END IF;
  ELSIF NEW.attempt_number<>OLD.attempt_number OR NEW.object_key<>OLD.object_key OR
    NEW.bucket<>OLD.bucket OR NEW.lease_expires_at<>OLD.lease_expires_at OR
    OLD.status<>'receiving' OR NEW.status NOT IN ('stored','failed') THEN
   RAISE EXCEPTION 'scan_attempt_conflict' USING ERRCODE='23514'; END IF;
 END IF;
 IF NEW.status='stored' THEN
  SELECT count(*) INTO n FROM scan_pages WHERE file_id=NEW.id;
  IF NEW.lease_expires_at<=clock_timestamp() OR NEW.page_count IS DISTINCT FROM n OR n=0 OR
    (SELECT max(page_index) FROM scan_pages WHERE file_id=NEW.id)<>n-1 THEN
   RAISE EXCEPTION 'scan_pages_incomplete' USING ERRCODE='23514'; END IF;
 END IF;
 RETURN NEW;
END $$;

CREATE FUNCTION guard_scan_page() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE f scan_files;
BEGIN
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'scan_page_immutable' USING ERRCODE='23514'; END IF;
 SELECT * INTO f FROM scan_files WHERE id=NEW.file_id FOR UPDATE;
 IF NOT FOUND OR f.status<>'receiving' OR f.lease_expires_at<=clock_timestamp() OR
   NEW.object_key<>regexp_replace(f.object_key,'original[.]pdf$','page-'||NEW.page_index||'.jpg')
 THEN
  RAISE EXCEPTION 'scan_page_source_invalid' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $$;
"""
ACTIONS = ["scan.batch.create", "scan.batch.read", "scan.file.upload", "scan.file.read"]
ROLE_IDS = [f"11111111-b13a-4000-8000-00000000000{i}" for i in (1, 2, 3)]


def install_guards_and_roles():
    for statement in GUARDS.split(";\n\n"):
        if statement.strip():
            op.execute(statement)
    for table, function, events in (
        ("scan_batches", "guard_security_immutable", "UPDATE OR DELETE"),
        ("scan_operations", "guard_security_immutable", "UPDATE OR DELETE"),
        ("scan_files", "guard_scan_file", "INSERT OR UPDATE OR DELETE"),
        ("scan_pages", "guard_scan_page", "INSERT OR UPDATE OR DELETE"),
    ):
        op.execute(
            f"CREATE TRIGGER protect_scan BEFORE {events} ON {table} "
            f"FOR EACH ROW EXECUTE FUNCTION {function}()"
        )
    bind = op.get_bind()
    for code in ACTIONS:
        bind.execute(
            sa.text(
                "INSERT INTO permission_definitions VALUES (:code,true,"
                "ARRAY['installation','exam_event','exam_session'])"
            ),
            dict(code=code),
        )
    for rid, name, codes in zip(
        ROLE_IDS,
        ["scan_operator", "scan_reader", "scan_deployer"],
        [ACTIONS, ["scan.batch.read", "scan.file.read"], ["security.grants.manage"] + ACTIONS],
        strict=True,
    ):
        bind.execute(
            sa.text("INSERT INTO security_role_versions VALUES (CAST(:rid AS uuid),:name,1,NULL)"),
            dict(rid=rid, name=name),
        )
        for code in codes:
            bind.execute(
                sa.text("INSERT INTO security_role_permissions VALUES (CAST(:rid AS uuid),:code)"),
                dict(rid=rid, code=code),
            )
        bind.execute(
            sa.text(
                "UPDATE security_role_versions SET sealed_at=clock_timestamp() "
                "WHERE id=CAST(:rid AS uuid)"
            ),
            dict(rid=rid),
        )


def remove_guards_and_roles():
    op.execute(
        "LOCK TABLE scan_batches,scan_files,scan_pages,scan_operations,security_grants "
        "IN ACCESS EXCLUSIVE MODE"
    )
    bind = op.get_bind()
    used = any(
        bind.scalar(sa.text(f"SELECT EXISTS(SELECT 1 FROM {table})"))
        for table in ["scan_batches", "scan_files", "scan_pages", "scan_operations"]
    )
    used = used or bind.scalar(
        sa.text(
            "SELECT EXISTS(SELECT 1 FROM security_grants "
            "WHERE role_version_id=ANY(CAST(:ids AS uuid[])))"
        ),
        dict(ids=ROLE_IDS),
    )
    if used:
        raise RuntimeError("scan_downgrade_requires_archived_new_data")
    for table in ("scan_batches", "scan_files", "scan_pages", "scan_operations"):
        op.execute(f"DROP TRIGGER protect_scan ON {table}")
    op.execute("DROP FUNCTION guard_scan_page()")
    op.execute("DROP FUNCTION guard_scan_file()")
    op.execute(
        "ALTER TABLE security_role_permissions DISABLE TRIGGER immutable_security_role_permissions"
    )
    op.execute("ALTER TABLE security_role_versions DISABLE TRIGGER immutable_security_role")
    for rid in ROLE_IDS:
        bind.execute(
            sa.text(
                "DELETE FROM security_role_permissions WHERE role_version_id=CAST(:rid AS uuid)"
            ),
            dict(rid=rid),
        )
        bind.execute(
            sa.text("DELETE FROM security_role_versions WHERE id=CAST(:rid AS uuid)"), dict(rid=rid)
        )
    op.execute(
        "ALTER TABLE security_role_permissions ENABLE TRIGGER immutable_security_role_permissions"
    )
    op.execute("ALTER TABLE security_role_versions ENABLE TRIGGER immutable_security_role")
    for code in ACTIONS:
        bind.execute(
            sa.text("DELETE FROM permission_definitions WHERE code=:code"), dict(code=code)
        )
